<script>
(function(){'use strict';const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s)),money=v=>'S/ '+Number(v||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}),num=v=>Number(v||0).toLocaleString('es-PE',{maximumFractionDigits:2}),esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])),today=new Date(),form=$('#filters');let state=null,catalogsLoaded=false;
const local=d=>{const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)};form.desde.value=local(new Date(today.getFullYear(),today.getMonth(),1));form.hasta.value=local(today);
function query(){return new URLSearchParams(new FormData(form)).toString()}function badge(v){const c=v==='Saludable'||v==='Alta'?'is-success':v==='Bajo'||v==='Media'?'is-warning':v==='Agotado'||v==='Crítico'?'is-danger':'is-info';return `<span class="kpi-badge ${c}">${esc(v)}</span>`}function financial(v){return state.permissions.financial?money(v):'<span class="financial-hidden">S/ 99,999</span>'}
function card(icon,label,value,foot='',cls=''){return `<article class="kpi-card"><i class="fa fa-${icon}"></i><span>${label}</span><strong class="${cls}">${value}</strong><small>${foot}</small></article>`}function bars(rows,label='etiqueta',value='venta',currency=true,limit=12){rows=(rows||[]).slice(0,limit);const max=Math.max(1,...rows.map(r=>Number(r[value]||0)));return rows.length?rows.map(r=>`<div class="kpi-hrow"><span title="${esc(r[label])}">${esc(r[label])}</span><div class="kpi-track"><i style="width:${Math.max(1,Number(r[value]||0)/max*100)}%"></i></div><b>${currency?money(r[value]):num(r[value])}</b></div>`).join(''):'<div class="kpi-empty">Sin datos en este periodo.</div>'}
function table(rows,cols){if(!rows||!rows.length)return '<div class="kpi-empty">Sin datos en este periodo.</div>';return `<table class="kpi-table"><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr>${cols.map(c=>`<td>${typeof c[2]==='function'?c[2](r,i):esc(r[c[0]])}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function select(name,rows){const el=form.elements[name],value=el.value;el.innerHTML='<option value="'+(name==='vendedor'?'':'0')+'">Todos</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.nombre)}</option>`).join('');el.value=value}
function render(){const s=state.summary,delta=s.variacion>=0?'positive':'negative';$('#summaryCards').innerHTML=card('money','Venta neta',money(s.venta),`${s.variacion>=0?'+':''}${num(s.variacion)}% vs periodo anterior`,delta)+card('line-chart','Utilidad bruta',financial(s.utilidad),`Margen ${num(s.margen)}%`)+card('ticket','Tickets',num(s.tickets),'Comprobantes válidos')+card('shopping-bag','Unidades',num(s.prendas),'Unidades vendidas')+card('calculator','Ticket promedio',money(s.ticket_promedio),'Venta neta / tickets')+card('percent','Descuentos',money(s.descuento),'Total otorgado');
$('#periodLabel').textContent=state.filters.fromDate+' al '+state.filters.toDate;const evo=state.evolution,max=Math.max(1,...evo.map(r=>+r.venta));$('#evolutionChart').innerHTML=evo.length?evo.map(r=>`<div class="kpi-bar" title="${esc(r.fecha)}: ${money(r.venta)}"><b>${evo.length<16?num(r.venta):''}</b><i style="height:${Math.max(2,+r.venta/max*100)}%"></i><small>${esc(r.fecha.slice(5))}</small></div>`).join(''):'<div class="kpi-empty">Sin ventas</div>';$('#topChart').innerHTML=bars(state.top,'producto','unidades',false,8);
const g=s.meta;$('#goalBox').innerHTML=`<h3>${money(g.actual)} de ${money(g.objetivo)}</h3><div class="kpi-progress"><i style="width:${Math.min(100,g.porcentaje)}%"></i></div><p><b>${num(g.porcentaje)}%</b> alcanzado · faltan ${money(g.faltante)}</p>`;$('#editMeta').classList.toggle('hidden',!state.permissions.admin);if(!state.permissions.financial){$$('.kpi-card').forEach(x=>{if(/Utilidad|Margen/i.test(x.textContent))x.querySelector('small')?.classList.add('financial-hidden')})}
$('#weekdayChart').innerHTML=bars(state.weekdays,'dia','venta');$('#hourChart').innerHTML=bars(state.hours,'hora','venta');$('#paymentChart').innerHTML=bars(state.payments,'medio','importe');$('#returnSummary').innerHTML='<div class="kpi-cards" style="padding:18px;grid-template-columns:repeat(3,1fr)">'+card('undo','Notas',state.return_summary.cantidad)+card('money','Monto',money(state.return_summary.importe))+card('percent','Sobre venta',num(state.return_summary.porcentaje)+'%')+'</div>';
$('#returnTable').innerHTML=table(state.returns,[['documento','Nota de crédito'],['referencia','Documento modificado'],['motivo','Motivo'],['vendedor','Vendedor'],['sucursal','Sucursal'],['unidades','Unidades',r=>num(r.unidades)],['importe','Importe',r=>money(r.importe)]]);
$('#categoryChart').innerHTML=bars(state.dimensions.categorias);$('#brandChart').innerHTML=bars(state.dimensions.marcas);$('#modelChart').innerHTML=bars(state.dimensions.modelos);
$('#productTable').innerHTML=table(state.top,[['rank','#',(r,i)=>i+1],['codigo','Codigo'],['producto','Producto'],['categoria','Categoria'],['marca','Marca'],['modelo','Modelo'],['unidades','Unidades',r=>num(r.unidades)],['venta','Venta',r=>money(r.venta)],['descuento','Descuento',r=>money(r.descuento)],['costo','Costo',r=>financial(r.costo)],['utilidad','Utilidad',r=>financial(r.utilidad)],['margen','Margen',r=>num(r.margen)+'%']]);
$('#lowProductTable').innerHTML=table(state.low_products,[['codigo','Codigo'],['producto','Producto'],['categoria','Categoria'],['marca','Marca'],['modelo','Modelo'],['stock','Stock',r=>num(r.stock)],['unidades_periodo','Vendidos',r=>num(r.unidades_periodo)],['ultima_venta','Ultima venta'],['dias_sin_venta','Dias sin movimiento',r=>r.dias_sin_venta===null?'Nunca':num(r.dias_sin_venta)],['valor','Valor stock',r=>financial(r.valor)],['rotacion','Rotacion',r=>badge(r.rotacion)]]);
const inv=state.inventory_summary;$('#inventoryCards').innerHTML=card('cubes','Valor inventario',financial(inv.valor),'Stock × costo')+card('exclamation-triangle','Stock crítico',num(inv.criticos),'Igual o menor al mínimo')+card('ban','Agotados',num(inv.agotados),'Stock en cero')+card('clock-o','Inmovilizado',financial(inv.inmovilizado),'Más de 90 días sin venta');
$('#inventoryTable').innerHTML=table(state.inventory,[['codigo','Codigo'],['producto','Producto'],['categoria','Categoria'],['marca','Marca'],['modelo','Modelo'],['almacen','Almacen'],['stock','Stock',r=>num(r.stock)],['stock_minimo','Minimo',r=>num(r.stock_minimo)],['estado','Estado',r=>badge(r.estado)],['ultima_venta','Ultima venta'],['dias_sin_venta','Dias sin venta',r=>r.dias_sin_venta===null?'Nunca':num(r.dias_sin_venta)],['valor','Valor',r=>financial(r.valor)],['sell_through','Sell through',r=>num(r.sell_through)+'%'],['rotacion','Rotacion',r=>badge(r.rotacion)]]);
$('#sellerTable').innerHTML=table(state.sellers,[['rank','#',(r,i)=>i+1],['nombre','Vendedor'],['tickets','Tickets'],['unidades','Unidades',r=>num(r.unidades)],['venta','Venta',r=>money(r.venta)],['ticket','Ticket promedio',r=>money(+r.venta/(+r.tickets||1))],['utilidad','Utilidad',r=>financial(r.utilidad)],['descuento','Descuento',r=>money(r.descuento)]]);
$('#clientTable').innerHTML=table(state.clients,[['rank','#',(r,i)=>i+1],['documento','Documento'],['cliente','Cliente'],['compras','Compras'],['venta','Compra total',r=>money(r.venta)],['promedio','Promedio línea',r=>money(r.promedio)],['primera_compra','Primera compra'],['ultima_compra','Última compra']]);
$('#branchTable').innerHTML=table(state.branches,[['sucursal','Sucursal'],['tickets','Tickets'],['unidades','Unidades',r=>num(r.unidades)],['venta','Ventas',r=>money(r.venta)],['ticket','Ticket promedio',r=>money(+r.venta/(+r.tickets||1))],['utilidad','Utilidad',r=>financial(r.utilidad)],['margen','Margen',r=>num(+r.venta?+r.utilidad/+r.venta*100:0)+'%']]);
$('#alerts').innerHTML=state.alerts.length?state.alerts.map(a=>`<div class="kpi-alert ${esc(a.level)}"><i class="fa fa-${a.level==='success'?'check-circle':a.level==='warning'?'exclamation-triangle':'bell'}"></i><div><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></div></div>`).join(''):'<div class="kpi-empty">No hay alertas para los filtros elegidos.</div>';
if(!catalogsLoaded){select('almacen',state.catalogs.almacenes);select('categoria',state.catalogs.categorias);select('marca',state.catalogs.marcas);select('vendedor',state.catalogs.vendedores);catalogsLoaded=true}}
async function load(){const loading=$('#loading');loading.classList.remove('hidden');try{const res=await fetch('/api/index.php/kpi/dashboard?'+query(),{credentials:'same-origin'}),json=await res.json();if(!res.ok)throw new Error(json.error+(json.detail?' '+json.detail:''));state=json;render()}catch(e){alert(e.message||'No se pudieron cargar los KPI.')}finally{loading.classList.add('hidden')}}
function activate(name){if(!['resumen','ventas','productos','inventario','vendedores','clientes','sucursales','alertas'].includes(name))name='resumen';$$('.kpi-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));$$('.kpi-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));if(location.hash!=='#'+name)history.replaceState(null,'','#'+name)}
form.addEventListener('submit',e=>{e.preventDefault();load()});$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)activate(b.dataset.tab)});window.addEventListener('hashchange',()=>activate(location.hash.slice(1)));$('#printBtn').onclick=()=>window.print();$$('[data-export]').forEach(b=>b.onclick=()=>{location.href='/api/index.php/kpi/exportar?seccion='+encodeURIComponent(b.dataset.export)+'&'+query()});$('#editMeta').onclick=async()=>{const value=prompt('Meta mensual en soles:',state.summary.meta.objetivo);if(value===null)return;const body=new URLSearchParams({meta:value}),res=await fetch('/api/index.php/kpi/meta',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),json=await res.json();if(!res.ok)return alert(json.error);load()};activate(location.hash.slice(1));load();
})();
</script></body></html>
